CREATE TABLE `import_usage` (
	`user_id` text PRIMARY KEY NOT NULL,
	`day` text NOT NULL,
	`count` integer DEFAULT 0 NOT NULL
);

CREATE TABLE `workspaces` (
	`book_id` text PRIMARY KEY NOT NULL,
	`revision` integer DEFAULT 1 NOT NULL,
	`data` text NOT NULL,
	FOREIGN KEY (`book_id`) REFERENCES `books`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE `food_preferences` (
	`user_id` text PRIMARY KEY NOT NULL,
	`revision` integer DEFAULT 1 NOT NULL,
	`data` text NOT NULL,
	`updated_at` integer NOT NULL
);

CREATE TABLE `account_ai_budgets` (
	`user_id` text PRIMARY KEY NOT NULL,
	`monthly_limit_micros` integer DEFAULT 1000000 NOT NULL,
	CONSTRAINT "account_ai_budget_range" CHECK("account_ai_budgets"."monthly_limit_micros" >= 0 AND "account_ai_budgets"."monthly_limit_micros" <= 1000000000000)
);
